    def test_invalid_psbtv0_with_version_field(self):
        """PSBTv0 but with PSBT_GLOBAL_VERSION set to 2 should be invalid"""
        hex_data = ""

        with pytest.raises(PSBTError):
            PSBT.parse(unhexlify(hex_data))

