    # Valid PSBTs
    def test_valid_psbtv2_minimal(self):
        """1 input, 2 output PSBTv2, required fields only should be valid"""
        hex_data = "70736274ff01020402000000010401010105010201fb040200000000010e200b0ad921419c1c8719735d72dc739f9ea9e0638d1fe4c1eef0f9944084815fc8010f0400000000000103080008af2f000000000104160014c430f64c4756da310dbd1a085572ef299926272c000103088bbdeb0b0000000001041600144dd193ac964a56ac1b9e1cca8454fe2f474f851300"

        psbt = PSBT.parse(unhexlify(hex_data))
        assert psbt.version == 2
        assert len(psbt.inputs) == 1
        assert len(psbt.outputs) == 2

